python
def priorityBasketProofStrip(readings):
    a=readings
    out=[]
    import heapq
    heap=a[:]
    heapq.heapify(heap)
    while heap: out.append(heapq.heappop(heap))
    return out


java
class Solution {
  public int[] priorityBasketProofStrip(int[] readings) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {PriorityQueue<Integer>heap=new PriorityQueue<>();for(int x:a)heap.add(x);while(!heap.isEmpty())out.add(heap.remove());}
    return out.stream().mapToInt(Integer::intValue).toArray();
  }
}
